PRAGMA foreign_keys=OFF;
BEGIN IMMEDIATE;
CREATE TEMP TABLE "issue24_migration_guard" ("ok" INTEGER NOT NULL CHECK("ok"=1));
CREATE TABLE "BusinessUnit" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL CHECK(length("name") BETWEEN 1 AND 100 AND trim("name")="name"),"active" INTEGER NOT NULL DEFAULT 1 CHECK("active" IN(0,1)),"created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "uq_business_unit_name" ON "BusinessUnit"("name");
CREATE TABLE "Product" ("id" TEXT NOT NULL PRIMARY KEY,"business_unit_id" TEXT NOT NULL,"name" TEXT NOT NULL CHECK(length("name") BETWEEN 1 AND 100 AND trim("name")="name"),"is_unclassified" INTEGER NOT NULL DEFAULT 0 CHECK("is_unclassified" IN(0,1)),"active" INTEGER NOT NULL DEFAULT 1 CHECK("active" IN(0,1)),"created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("business_unit_id") REFERENCES "BusinessUnit"("id") ON DELETE NO ACTION ON UPDATE NO ACTION);
CREATE UNIQUE INDEX "uq_product_parent_name" ON "Product"("business_unit_id","name"); CREATE INDEX "ix_product_business_unit" ON "Product"("business_unit_id");
CREATE UNIQUE INDEX "uq_product_unclassified" ON "Product"("business_unit_id") WHERE "is_unclassified"=1;
CREATE TABLE "CadSite" ("id" TEXT NOT NULL PRIMARY KEY,"product_id" TEXT NOT NULL,"name" TEXT NOT NULL CHECK(length("name") BETWEEN 1 AND 100 AND trim("name")="name"),"kind" TEXT NOT NULL DEFAULT 'SITE' CHECK("kind" IN('SITE','LEGAL_ENTITY')),"active" INTEGER NOT NULL DEFAULT 1 CHECK("active" IN(0,1)),"created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("product_id") REFERENCES "Product"("id") ON DELETE NO ACTION ON UPDATE NO ACTION);
CREATE UNIQUE INDEX "uq_site_parent_name" ON "CadSite"("product_id","name"); CREATE INDEX "ix_site_product" ON "CadSite"("product_id");
CREATE TABLE "Building" ("id" TEXT NOT NULL PRIMARY KEY,"site_id" TEXT NOT NULL,"name" TEXT NOT NULL CHECK(length("name") BETWEEN 1 AND 100 AND trim("name")="name"),"active" INTEGER NOT NULL DEFAULT 1 CHECK("active" IN(0,1)),"created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("site_id") REFERENCES "CadSite"("id") ON DELETE NO ACTION ON UPDATE NO ACTION);
CREATE UNIQUE INDEX "uq_building_parent_name" ON "Building"("site_id","name"); CREATE INDEX "ix_building_site" ON "Building"("site_id");

INSERT INTO "BusinessUnit"("id","name","created_at","updated_at") SELECT lower(substr(hex(randomblob(16)),1,8)||'-'||substr(hex(randomblob(16)),1,4)||'-4'||substr(hex(randomblob(16)),1,3)||'-a'||substr(hex(randomblob(16)),1,3)||'-'||substr(hex(randomblob(16)),1,12)),business_unit,min(created_at),max(updated_at) FROM "CadLocation" GROUP BY business_unit;
INSERT INTO "Product"("id","business_unit_id","name","is_unclassified","created_at","updated_at") SELECT lower(substr(hex(randomblob(16)),1,8)||'-'||substr(hex(randomblob(16)),1,4)||'-4'||substr(hex(randomblob(16)),1,3)||'-a'||substr(hex(randomblob(16)),1,3)||'-'||substr(hex(randomblob(16)),1,12)),id,'미분류',1,created_at,updated_at FROM "BusinessUnit";
INSERT INTO "CadSite"("id","product_id","name","kind","created_at","updated_at") SELECT lower(substr(hex(randomblob(16)),1,8)||'-'||substr(hex(randomblob(16)),1,4)||'-4'||substr(hex(randomblob(16)),1,3)||'-a'||substr(hex(randomblob(16)),1,3)||'-'||substr(hex(randomblob(16)),1,12)),p.id,l.site,'SITE',min(l.created_at),max(l.updated_at) FROM "CadLocation" l JOIN "BusinessUnit" b ON b.name=l.business_unit JOIN "Product" p ON p.business_unit_id=b.id AND p.name='미분류' GROUP BY p.id,l.site;
INSERT INTO "Building"("id","site_id","name","created_at","updated_at") SELECT lower(substr(hex(randomblob(16)),1,8)||'-'||substr(hex(randomblob(16)),1,4)||'-4'||substr(hex(randomblob(16)),1,3)||'-a'||substr(hex(randomblob(16)),1,3)||'-'||substr(hex(randomblob(16)),1,12)),s.id,l.building,min(l.created_at),max(l.updated_at) FROM "CadLocation" l JOIN "BusinessUnit" bu ON bu.name=l.business_unit JOIN "Product" p ON p.business_unit_id=bu.id AND p.name='미분류' JOIN "CadSite" s ON s.product_id=p.id AND s.name=l.site GROUP BY s.id,l.building;

CREATE TABLE "new_CadLocation" ("id" TEXT NOT NULL PRIMARY KEY,"building_id" TEXT NOT NULL,"name" TEXT NOT NULL CHECK(length("name") BETWEEN 1 AND 100 AND trim("name")="name"),"active" INTEGER NOT NULL DEFAULT 1 CHECK("active" IN(0,1)),"current_version_id" TEXT,"next_version" INTEGER NOT NULL DEFAULT 1 CHECK("next_version">=1),"created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("building_id") REFERENCES "Building"("id") ON DELETE NO ACTION ON UPDATE NO ACTION,FOREIGN KEY("id","current_version_id") REFERENCES "CadFileVersion"("location_id","id") ON DELETE NO ACTION ON UPDATE NO ACTION);
INSERT INTO "new_CadLocation"("id","building_id","name","active","current_version_id","next_version","created_at","updated_at") SELECT l.id,bl.id,l.floor,1,l.current_version_id,l.next_version,l.created_at,l.updated_at FROM "CadLocation" l JOIN "BusinessUnit" bu ON bu.name=l.business_unit JOIN "Product" p ON p.business_unit_id=bu.id AND p.name='미분류' JOIN "CadSite" s ON s.product_id=p.id AND s.name=l.site JOIN "Building" bl ON bl.site_id=s.id AND bl.name=l.building;
INSERT INTO "issue24_migration_guard"("ok") SELECT CASE WHEN (SELECT count(*) FROM "CadLocation")=(SELECT count(*) FROM "new_CadLocation") AND NOT EXISTS(SELECT 1 FROM "new_CadLocation" WHERE "building_id" IS NULL) THEN 1 ELSE 0 END;
DROP TABLE "CadLocation"; ALTER TABLE "new_CadLocation" RENAME TO "CadLocation";
CREATE UNIQUE INDEX "uq_floor_parent_name" ON "CadLocation"("building_id","name"); CREATE UNIQUE INDEX "uq_location_current_owner" ON "CadLocation"("id","current_version_id"); CREATE INDEX "ix_floor_building" ON "CadLocation"("building_id"); CREATE INDEX "ix_location_current" ON "CadLocation"("current_version_id");
CREATE TRIGGER "cad_location_next_version_insert" BEFORE INSERT ON "CadLocation" WHEN NEW.next_version<1 BEGIN SELECT RAISE(ABORT,'next_version must be positive'); END;
CREATE TRIGGER "cad_location_next_version_update" BEFORE UPDATE OF next_version ON "CadLocation" WHEN NEW.next_version<OLD.next_version BEGIN SELECT RAISE(ABORT,'next_version cannot decrease'); END;
INSERT INTO "issue24_migration_guard"("ok") SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM pragma_foreign_key_check) THEN 1 ELSE 0 END;
DROP TABLE "issue24_migration_guard";
COMMIT;
PRAGMA foreign_keys=ON;
